function analyzeSentiment(text2) {
  const lower = text2.toLowerCase();
  const positiveWords = [
    "excelente",
    "perfecto",
    "genial",
    "me encanta",
    "s\xFAper",
    "incre\xEDble",
    "maravilloso",
    "hermoso",
    "ideal",
    "justo lo que",
    "exactamente",
    "me gusta",
    "interesante",
    "bien",
    "bueno",
    "gracias"
  ];
  const negativeWords = [
    "caro",
    "no puedo",
    "no tengo",
    "malo",
    "dif\xEDcil",
    "complicado",
    "no me gusta",
    "no sirve",
    "decepcion",
    "molesto",
    "problema",
    "no funciona",
    "tarde",
    "lento",
    "mal",
    "no estoy segur"
  ];
  const veryNegativeWords = [
    "horrible",
    "p\xE9simo",
    "terrible",
    "desastre",
    "fraude",
    "estafa"
  ];
  let positiveCount = 0;
  let negativeCount = 0;
  let veryNegativeCount = 0;
  for (const word of positiveWords) {
    if (lower.includes(word)) positiveCount++;
  }
  for (const word of negativeWords) {
    if (lower.includes(word)) negativeCount++;
  }
  for (const word of veryNegativeWords) {
    if (lower.includes(word)) veryNegativeCount++;
  }
  const score = positiveCount * 0.3 - negativeCount * 0.3 - veryNegativeCount * 0.5;
  const normalizedScore = Math.max(-1, Math.min(1, score));
  let sentiment;
  let confidence;
  if (normalizedScore > 0.2) {
    sentiment = "positivo";
    confidence = Math.min(0.9, 0.5 + positiveCount * 0.1);
  } else if (normalizedScore < -0.2) {
    sentiment = "negativo";
    confidence = Math.min(0.9, 0.5 + (negativeCount + veryNegativeCount) * 0.1);
  } else {
    sentiment = "neutral";
    confidence = 0.7;
  }
  return { sentiment, score: normalizedScore, confidence };
}
